<template>
  <div class="dev-dash tw-min-h-screen tw-bg-ink tw-text-slate-200" @pointermove="onDashboardPointerMove">
    <button
      v-if="mobileMenuOpen"
      class="d-mobile-backdrop"
      type="button"
      aria-label="Close dashboard navigation"
      @click="closeMobileMenu"
    ></button>

    <!-- ── Sidebar ─────────────────────────────────────────────────────── -->
    <aside id="developer-dashboard-nav" :class="['d-sidebar', 'tw-border-line', 'tw-bg-panel', { 'is-mobile-open': mobileMenuOpen, 'is-collapsed': sidebarCollapsed }]">
      <div class="d-logo">
        <img class="d-mark" src="@/assets/almax-mark.png" alt="Almax logo" />
        <div>
          <div class="d-brand">ALMAX</div>
          <div class="d-brand-sub">DEV CONSOLE</div>
        </div>
        <button class="d-collapse" type="button" :aria-label="sidebarCollapsed ? 'Expand dashboard navigation' : 'Collapse dashboard navigation'" :title="sidebarCollapsed ? 'Expand navigation' : 'Collapse navigation'" @click="toggleSidebar">
          <svg viewBox="0 0 24 24" aria-hidden="true"><path d="m15 18-6-6 6-6" /></svg>
        </button>
        <button class="d-mobile-close" type="button" aria-label="Close dashboard navigation" @click="closeMobileMenu">
          <span></span><span></span>
        </button>
      </div>

      <nav class="d-nav">
        <template v-for="item in navItems" :key="item.id">
          <p v-if="item.id === 'overview'" class="d-nav-group">Analytics</p>
          <p v-if="item.id === 'wallet'" class="d-nav-group d-nav-group--spaced">Operations</p>
          <button
            :class="['d-nav-btn', { active: activeSection === item.id }]"
            :title="sidebarCollapsed ? item.label : undefined"
            @click="selectSection(item.id)"
          >
            <span class="d-nav-icon" v-html="item.icon"></span>
            <span class="d-nav-copy">
              <span class="d-nav-label">{{ item.label }}</span>
              <span class="d-nav-desc">{{ item.desc }}</span>
            </span>
            <span v-if="item.id === 'commission'" class="d-private-dot"></span>
          </button>
        </template>
      </nav>

      <div class="d-user-strip">
        <span class="d-user-av">D</span>
        <span class="d-user-info">
          <strong>almaxdev</strong>
          <small>Developer</small>
        </span>
      </div>

      <button class="d-logout" @click="logout">Sign out</button>
    </aside>

    <!-- ── Main Panel ──────────────────────────────────────────────────── -->
    <main class="d-main tw-min-w-0 tw-bg-ink">
      <header class="d-header tw-border-line tw-bg-panel/95 tw-backdrop-blur">
        <div class="d-header-intro">
          <button
            class="d-mobile-toggle"
            type="button"
            aria-label="Open dashboard navigation"
            aria-controls="developer-dashboard-nav"
            :aria-expanded="mobileMenuOpen"
            @click="toggleMobileMenu"
          >
            <span></span><span></span><span></span>
          </button>
          <div>
            <p class="d-kicker">Developer Analytics</p>
            <h1 class="d-title">{{ currentSection.label }}</h1>
            <p class="d-subtitle">{{ currentSection.desc }}</p>
          </div>
        </div>
        <div class="d-header-right">
          <span class="d-date">{{ todayDate }}</span>
          <span class="d-mode-badge">{{ isPreviewMode ? 'LOCAL PREVIEW' : 'DEV MODE' }}</span>
          <button class="d-refresh" @click="fetchAnalytics" :disabled="loading" title="Refresh data">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="23 4 23 10 17 10"/><polyline points="1 20 1 14 7 14"/><path d="M3.51 9a9 9 0 0 1 14.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0 0 20.49 15"/></svg>
          </button>
        </div>
      </header>

      <!-- Loading -->
      <div v-if="loading" class="d-loading">
        <div class="d-spinner"></div>
        <p>Loading analytics…</p>
      </div>

      <!-- Error -->
      <div v-else-if="error" class="d-error-state">
        <p>{{ error }}</p>
        <button @click="fetchAnalytics">Retry</button>
      </div>

      <!-- ── Content ──────────────────────────────────────────────────── -->
      <div v-else-if="analytics" class="d-body tw-mx-auto tw-w-full tw-max-w-[1600px] tw-space-y-6">

        <!-- ========== OVERVIEW ========================================= -->
        <div v-if="activeSection === 'overview'">
          <!-- KPI Row 1 -->
          <div class="kpi-grid">
            <div class="kpi-card kpi-green">
              <span class="kpi-graphic" aria-hidden="true"><svg viewBox="0 0 64 36"><path d="M3 29 15 22l10 3 13-16 10 8L61 4"/><path class="kpi-graphic-base" d="M3 33h58"/></svg></span>
              <p class="kpi-label">Total Revenue</p>
              <p class="kpi-value">{{ formatUGX(f.total_revenue) }}</p>
              <p class="kpi-sub">All confirmed payments</p>
            </div>
            <div class="kpi-card kpi-blue">
              <span class="kpi-graphic kpi-graphic-bars" aria-hidden="true"><svg viewBox="0 0 54 38"><path d="M5 33V20h8v13M23 33V11h8v22M41 33V4h8v29M3 33h48"/></svg></span>
              <p class="kpi-label">This Month</p>
              <p class="kpi-value">{{ formatUGX(f.revenue_this_month) }}</p>
              <p class="kpi-sub">{{ formatUGX(f.revenue_this_week) }} this week</p>
            </div>
            <div class="kpi-card kpi-accent">
              <span class="kpi-graphic kpi-graphic-ring" aria-hidden="true"><svg viewBox="0 0 48 48"><circle cx="24" cy="24" r="17"/><path d="M24 7a17 17 0 0 1 15 9M24 15v18M18 20c0-3 2-5 6-5s6 2 6 5-2 4-6 4-6 2-6 5 2 4 6 4 6-2 6-5"/></svg></span>
              <p class="kpi-label">Available Commission</p>
              <p class="kpi-value">{{ formatUGX(currentCommission) }}</p>
              <p class="kpi-sub">{{ formatUGX(c.total_withdrawn) }} withdrawn</p>
            </div>
            <div class="kpi-card kpi-teal">
              <span class="kpi-graphic kpi-graphic-transfer" aria-hidden="true"><svg viewBox="0 0 52 40"><path d="M5 12h36m0 0-7-7m7 7-7 7M47 28H11m0 0 7-7m-7 7 7 7"/></svg></span>
              <p class="kpi-label">Recorded Commission</p>
              <p class="kpi-value">{{ formatUGX(c.total_earned) }}</p>
              <p class="kpi-sub">{{ formatUGX(c.wallet_received ?? c.total_paid) }} paid to commission wallet</p>
            </div>
          </div>

          <!-- KPI Row 2 -->
          <div class="kpi-grid" style="margin-top:14px">
            <div class="kpi-card">
              <span class="kpi-graphic" aria-hidden="true"><svg viewBox="0 0 64 36"><path d="m3 27 9-4 8 3 9-14 9 7 9-9 14 5"/><path class="kpi-graphic-base" d="M3 33h58"/></svg></span>
              <p class="kpi-label">Today's Revenue</p>
              <p class="kpi-value kpi-value--md">{{ formatUGX(f.revenue_today) }}</p>
              <p class="kpi-sub">{{ formatNum(f.today?.confirmed_count) }} confirmed · {{ f.today?.timezone || 'Africa/Kampala' }}</p>
            </div>
            <div class="kpi-card">
              <span class="kpi-graphic kpi-graphic-people" aria-hidden="true"><svg viewBox="0 0 50 42"><circle cx="19" cy="14" r="7"/><path d="M5 38c1-9 6-14 14-14s13 5 14 14M32 9c7 0 11 4 11 10s-4 10-10 10"/></svg></span>
              <p class="kpi-label">Total Users</p>
              <p class="kpi-value kpi-value--md">{{ formatNum(u.total) }}</p>
              <p class="kpi-sub">+{{ u.new_this_month }} this month</p>
            </div>
            <div class="kpi-card">
              <span class="kpi-graphic kpi-graphic-stack" aria-hidden="true"><svg viewBox="0 0 52 40"><path d="m26 4 21 10-21 10L5 14 26 4Z"/><path d="m7 22 19 9 19-9M7 29l19 9 19-9"/></svg></span>
              <p class="kpi-label">Active Subscriptions</p>
              <p class="kpi-value kpi-value--md">{{ formatNum(s.active_total) }}</p>
            </div>
            <div class="kpi-card kpi-warn">
              <span class="kpi-graphic kpi-graphic-clock" aria-hidden="true"><svg viewBox="0 0 48 48"><circle cx="24" cy="24" r="18"/><path d="M24 13v12l8 5"/></svg></span>
              <p class="kpi-label">Pending Payments</p>
              <p class="kpi-value kpi-value--md">{{ formatNum(analytics.payments.pending_count) }}</p>
              <p class="kpi-sub">Awaiting confirmation</p>
            </div>
          </div>

          <div class="finance-reconcile" :class="auditHealthy ? 'finance-reconcile--ok' : 'finance-reconcile--warn'">
            <span>Today: <strong>{{ formatNum(f.today?.attempted_count) }} attempts</strong> ({{ formatUGX(f.today?.attempted_amount) }})</span>
            <span>Failed today: <strong>{{ formatNum(f.today?.failed_count) }}</strong> ({{ formatUGX(f.today?.failed_amount) }})</span>
            <span>Ledger rows: <strong>{{ formatNum(a.ledger_count) }}</strong></span>
            <span>Audit: <strong>{{ auditHealthy ? 'Reconciled' : 'Needs review' }}</strong></span>
            <span>As of: <strong>{{ fmtDateTime(a.as_of) }}</strong></span>
          </div>

          <!-- Charts row -->
          <div class="chart-row">
            <!-- Revenue chart -->
            <div class="chart-card">
              <div class="chart-heading">
                <div><p class="chart-title">Revenue</p><p class="chart-total">{{ formatUGX(f.total_revenue) }} total</p></div>
                <span class="chart-period">30 days</span>
              </div>
              <DeveloperChart :points="revenueChart" value-key="amount" value-type="currency" accent="#4fd1c5" aria-label="Revenue during the last 30 days" empty-text="No confirmed revenue in the last 30 days" />
            </div>

            <!-- Signups chart -->
            <div class="chart-card">
              <div class="chart-heading">
                <div><p class="chart-title">New users</p><p class="chart-total">{{ u.new_this_month }} this month</p></div>
                <span class="chart-period">30 days</span>
              </div>
              <DeveloperChart type="bar" :points="signupsChart" value-key="count" accent="#a78bfa" aria-label="New users during the last 30 days" empty-text="No signups in the last 30 days" />
            </div>
          </div>
        </div>

        <!-- ========== FINANCE ========================================== -->
        <div v-if="activeSection === 'finance'">
          <!-- Summary cards -->
          <div class="kpi-grid">
            <div class="kpi-card kpi-green">
              <p class="kpi-label">Confirmed Revenue</p>
              <p class="kpi-value">{{ formatUGX(f.by_status?.confirmed?.amount ?? 0) }}</p>
              <p class="kpi-sub">{{ formatNum(f.by_status?.confirmed?.count ?? 0) }} payments</p>
            </div>
            <div class="kpi-card">
              <p class="kpi-label">Pending Amount</p>
              <p class="kpi-value kpi-value--md">{{ formatUGX(f.by_status?.pending?.amount ?? 0) }}</p>
              <p class="kpi-sub">{{ formatNum(f.by_status?.pending?.count ?? 0) }} payments</p>
            </div>
            <div class="kpi-card kpi-red">
              <p class="kpi-label">Failed Payments</p>
              <p class="kpi-value kpi-value--md">{{ formatNum(f.by_status?.failed?.count ?? 0) }}</p>
              <p class="kpi-sub">{{ formatUGX(f.by_status?.failed?.amount ?? 0) }} attempted, not collected</p>
            </div>
            <div class="kpi-card kpi-blue">
              <p class="kpi-label">All Payment Attempts</p>
              <p class="kpi-value kpi-value--md">{{ formatUGX(f.attempted_amount) }}</p>
              <p class="kpi-sub">{{ formatNum(f.attempted_count) }} attempts · {{ Number(f.confirmation_rate || 0).toFixed(1) }}% confirmed</p>
            </div>
          </div>

          <div class="kpi-grid" style="margin-top:14px">
            <div class="kpi-card kpi-green">
              <p class="kpi-label">Confirmed Today</p>
              <p class="kpi-value kpi-value--md">{{ formatUGX(f.today?.confirmed_amount) }}</p>
              <p class="kpi-sub">{{ formatNum(f.today?.confirmed_count) }} confirmations · Kampala time</p>
            </div>
            <div class="kpi-card kpi-blue">
              <p class="kpi-label">Attempts Today</p>
              <p class="kpi-value kpi-value--md">{{ formatNum(f.today?.attempted_count) }}</p>
              <p class="kpi-sub">{{ formatUGX(f.today?.attempted_amount) }} attempted</p>
            </div>
            <div class="kpi-card kpi-red">
              <p class="kpi-label">Failed Today</p>
              <p class="kpi-value kpi-value--md">{{ formatNum(f.today?.failed_count) }}</p>
              <p class="kpi-sub">{{ formatUGX(f.today?.failed_amount) }} not collected</p>
            </div>
            <div class="kpi-card" :class="auditHealthy ? 'kpi-green' : 'kpi-warn'">
              <p class="kpi-label">Ledger Audit</p>
              <p class="kpi-value kpi-value--md">{{ auditHealthy ? 'Reconciled' : 'Review' }}</p>
              <p class="kpi-sub">{{ formatNum(a.ledger_count) }} preserved payment rows</p>
            </div>
          </div>

          <div class="finance-reconcile" :class="Number(f.reconciliation_difference || 0) === 0 ? 'finance-reconcile--ok' : 'finance-reconcile--warn'">
            <span>This month: <strong>{{ formatUGX(f.revenue_this_month) }}</strong></span>
            <span>This week: <strong>{{ formatUGX(f.revenue_this_week) }}</strong></span>
            <span>Unclassified: <strong>{{ formatUGX(f.unclassified_amount) }}</strong> ({{ formatNum(f.unclassified_count) }})</span>
            <span>Ledger difference: <strong>{{ formatUGX(f.reconciliation_difference) }}</strong></span>
            <span>Missing confirmation time: <strong>{{ formatNum(a.confirmed_missing_timestamp_count) }}</strong></span>
            <span>Confirmed without transaction ID: <strong>{{ formatNum(a.confirmed_missing_transaction_count) }}</strong></span>
            <span>Preserved after subscription deletion: <strong>{{ formatNum(a.preserved_without_subscription_count) }}</strong></span>
          </div>

          <div class="two-col-grid" style="margin-top:24px">
            <!-- Revenue by Plan -->
            <div class="section-card">
              <p class="section-card-title">Revenue by Plan</p>
              <div class="hbar-list">
                <div v-for="(value, key) in f.by_plan" :key="key" class="hbar-row">
                  <span class="hbar-label">{{ capitalize(key) }}</span>
                  <div class="hbar-track">
                    <div class="hbar-fill hbar-fill--accent" :style="{ width: hBarW(value, maxPlanRevenue) + '%' }"></div>
                  </div>
                  <span class="hbar-value">{{ formatUGX(value) }}</span>
                </div>
                <p v-if="!Object.keys(f.by_plan || {}).length" class="empty-msg">No data yet</p>
              </div>
            </div>

            <!-- Revenue by Payment Method -->
            <div class="section-card">
              <p class="section-card-title">Revenue by Payment Method</p>
              <div class="hbar-list">
                <div v-for="(value, key) in f.by_method" :key="key" class="hbar-row">
                  <span class="hbar-label">{{ key.toUpperCase() }}</span>
                  <div class="hbar-track">
                    <div class="hbar-fill hbar-fill--teal" :style="{ width: hBarW(value, maxMethodRevenue) + '%' }"></div>
                  </div>
                  <span class="hbar-value">{{ formatUGX(value) }}</span>
                </div>
                <p v-if="!Object.keys(f.by_method || {}).length" class="empty-msg">No data yet</p>
              </div>
            </div>

            <div class="section-card">
              <p class="section-card-title">Revenue by Gateway</p>
              <div class="hbar-list">
                <div v-for="(row, key) in f.by_provider" :key="key" class="hbar-row">
                  <span class="hbar-label">{{ key.toUpperCase() }}</span>
                  <div class="hbar-track">
                    <div class="hbar-fill hbar-fill--blue" :style="{ width: hBarW(row.amount, maxProviderRevenue) + '%' }"></div>
                  </div>
                  <span class="hbar-value">{{ formatUGX(row.amount) }} · {{ formatNum(row.count) }}</span>
                </div>
                <p v-if="!Object.keys(f.by_provider || {}).length" class="empty-msg">No data yet</p>
              </div>
            </div>
          </div>

          <!-- Revenue trend chart -->
          <div class="chart-card" style="margin-top:24px">
            <div class="chart-heading">
              <div><p class="chart-title">Daily revenue trend</p><p class="chart-total">Confirmed collections</p></div>
              <span class="chart-period">30 days</span>
            </div>
            <DeveloperChart :points="revenueChart" value-key="amount" value-type="currency" accent="#4fd1c5" aria-label="Daily confirmed revenue during the last 30 days" empty-text="No confirmed revenue in the last 30 days" />
          </div>

          <div class="section-card" style="margin-top:24px">
            <p class="section-card-title">Recent Payment Ledger</p>
            <p class="section-card-sub">Confirmation time drives revenue. Attempt time is shown separately. Phone numbers are masked.</p>
            <div class="table-wrap">
              <table class="data-table">
                <thead>
                  <tr>
                    <th>#</th>
                    <th>Attempted</th>
                    <th>Confirmed / Failed</th>
                    <th>Status</th>
                    <th>Amount</th>
                    <th>Method</th>
                    <th>Gateway</th>
                    <th>Phone</th>
                    <th>Reference</th>
                  </tr>
                </thead>
                <tbody>
                  <tr v-for="row in paymentLedger.rows" :key="row.id">
                    <td data-label="Record" class="td-muted">#{{ row.id }}</td>
                    <td data-label="Attempted" class="td-date">{{ fmtDateTime(row.created_at) }}</td>
                    <td data-label="Completed" class="td-date">{{ fmtDateTime(row.confirmed_at || row.failed_at) }}</td>
                    <td data-label="Status"><span :class="['status-badge', paymentStatusClass(row.status)]">{{ capitalize(row.status) }}</span></td>
                    <td data-label="Amount" class="td-amount">{{ formatUGX(row.amount) }}</td>
                    <td data-label="Method" class="td-method">{{ (row.payment_method || '—').toUpperCase() }}</td>
                    <td data-label="Gateway" class="td-method">{{ (row.provider || 'jpesa').toUpperCase() }}</td>
                    <td data-label="Phone" class="td-muted">{{ row.phone || '—' }}</td>
                    <td data-label="Reference" class="td-muted"><code>{{ row.payment_reference || row.transaction_id || '—' }}</code></td>
                  </tr>
                  <tr v-if="!paymentLedger.rows.length && !paymentLedger.loading">
                    <td colspan="9" class="td-empty">No payment ledger rows are available.</td>
                  </tr>
                </tbody>
              </table>
            </div>
            <div class="table-pagination" aria-live="polite">
              <div>
                <span>Showing {{ formatNum(paymentLedger.rows.length) }} of {{ formatNum(paymentLedger.total) }}</span>
                <small v-if="paymentLedger.error">{{ paymentLedger.error }}</small>
              </div>
              <button v-if="paymentLedger.hasMore || paymentLedger.error" type="button" :disabled="paymentLedger.loading" @click="fetchLedger('payment')">
                {{ paymentLedger.loading ? 'Loading…' : paymentLedger.error ? 'Try again' : 'Load 10 more' }}
              </button>
            </div>
            <p class="ledger-note">Ledger deletion protection started on 22 Oct 2026. Records deleted before that cutover cannot be reconstructed from the current database.</p>
          </div>
        </div>

        <!-- ========== COMMISSION ======================================== -->
        <div v-if="activeSection === 'commission'">
          <!-- Rate Banner -->
          <div class="comm-banner" :class="c.enabled ? 'comm-banner--active' : 'comm-banner--inactive'">
            <div class="comm-banner-left">
              <span class="comm-rate-badge">{{ (c.ratio * 100).toFixed(0) }}%</span>
              <div>
                <p class="comm-banner-title">
                  Platform Commission
                  <span :class="['comm-live-pill', c.enabled ? 'comm-live-pill--on' : 'comm-live-pill--off']">
                    {{ c.enabled ? '● LIVE' : '○ DISABLED' }}
                  </span>
                </p>
                <p class="comm-banner-sub">
                  <template v-if="c.enabled">Active — available balance is reduced by recorded commission withdrawals.</template>
                  <template v-else>Disabled — set <code>PAYMENT_AGENT_COMMISSION_ENABLED=true</code> in .env to activate.</template>
                </p>
              </div>
            </div>
            <div class="comm-banner-right">
              <div class="comm-stat">
                <span class="comm-stat-label">Ratio</span>
                <span class="comm-stat-val">{{ (c.ratio * 100).toFixed(1) }}%</span>
              </div>
              <div class="comm-stat">
                <span class="comm-stat-label">Available</span>
                <span class="comm-stat-val" :class="currentCommission > 0 ? 'text-accent' : ''">{{ formatUGX(currentCommission) }}</span>
              </div>
              <div class="comm-stat">
                <span class="comm-stat-label">Recorded</span>
                <span class="comm-stat-val">{{ formatUGX(c.total_earned) }}</span>
              </div>
            </div>
          </div>

          <!-- Commission KPI cards -->
          <div class="kpi-grid" style="margin-top:20px">
            <div class="kpi-card kpi-accent">
              <p class="kpi-label">Recorded Total</p>
              <p class="kpi-value">{{ formatUGX(c.total_earned) }}</p>
              <p class="kpi-sub">All tracked commission</p>
            </div>
            <div class="kpi-card kpi-green">
              <p class="kpi-label">Available Now</p>
              <p class="kpi-value">{{ formatUGX(currentCommission) }}</p>
              <p class="kpi-sub">After recorded withdrawals</p>
            </div>
            <div class="kpi-card kpi-blue">
              <p class="kpi-label">Withdrawn</p>
              <p class="kpi-value kpi-value--md">{{ formatUGX(c.total_withdrawn) }}</p>
              <p class="kpi-sub">{{ formatNum(c.withdrawals?.length ?? 0) }} recent records</p>
            </div>
            <div class="kpi-card kpi-warn">
              <p class="kpi-label">Paid to wallet</p>
              <p class="kpi-value kpi-value--md">{{ formatUGX(c.wallet_received ?? c.total_paid) }}</p>
              <p class="kpi-sub">{{ formatNum(c.by_status?.completed?.count ?? 0) }} transfers completed</p>
            </div>
          </div>

          <div class="kpi-grid" style="margin-top:14px">
            <div class="kpi-card">
              <p class="kpi-label">Accrued Relworx Commission</p>
              <p class="kpi-value kpi-value--md">{{ formatUGX(c.by_status?.accrued?.amount ?? 0) }}</p>
              <p class="kpi-sub">{{ formatNum(c.by_status?.accrued?.count ?? 0) }} ledger credits</p>
            </div>
            <div class="kpi-card">
              <p class="kpi-label">Processing Commission</p>
              <p class="kpi-value kpi-value--md">{{ formatUGX(c.by_status?.processing?.amount ?? 0) }}</p>
              <p class="kpi-sub">{{ formatNum(c.by_status?.processing?.count ?? 0) }} transfers in progress</p>
            </div>
            <div class="kpi-card kpi-red">
              <p class="kpi-label">Failed Commission</p>
              <p class="kpi-value kpi-value--md">{{ formatUGX(c.by_status?.failed?.amount ?? 0) }}</p>
              <p class="kpi-sub">{{ formatNum(c.by_status?.failed?.count ?? 0) }} transfers need retry</p>
            </div>
            <div class="kpi-card" :class="Number(c.untracked_payment_count || 0) ? 'kpi-warn' : 'kpi-green'">
              <p class="kpi-label">Commission Coverage</p>
              <p class="kpi-value kpi-value--md">{{ formatNum(c.tracked_payment_count) }} / {{ formatNum(c.confirmed_payment_count) }}</p>
              <p class="kpi-sub">{{ formatUGX(c.untracked_payment_revenue) }} confirmed revenue untracked</p>
            </div>
          </div>

          <div class="section-card withdrawal-card" style="margin-top:24px">
            <div class="withdrawal-head">
              <div>
