  background: rgba(239,68,68,.055);
}
.comm-live-pill {
  display: inline-flex;
  align-items: center;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.05em;
  padding: 2px 8px;
  border-radius: 20px;
  margin-left: 8px;
  vertical-align: middle;
}
.comm-live-pill--on  { background: rgba(16,185,129,0.18); color: #10b981; border: 1px solid rgba(16,185,129,0.4); }
.comm-live-pill--off { background: rgba(239,68,68,0.15);  color: #ef4444; border: 1px solid rgba(239,68,68,0.3); }

.comm-banner-left {
  display: flex;
  align-items: center;
  gap: 16px;
}

.comm-rate-badge {
  font-size: 32px;
  font-weight: 900;
  color: #8fb3d9;
  line-height: 1;
  flex-shrink: 0;
}

.comm-banner-title {
  font-size: 15px;
  font-weight: 700;
  color: #f3f4f6;
  margin: 0 0 4px;
}

.comm-banner-sub {
  font-size: 12px;
  color: #6b7280;
  margin: 0;
  line-height: 1.4;
}

.comm-banner-right {
  display: flex;
  gap: 24px;
  flex-shrink: 0;
}

.comm-stat {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
}

.comm-stat-label {
  font-size: 9px;
  font-weight: 700;
  color: #6b7280;
  letter-spacing: 1px;
  text-transform: uppercase;
}

.comm-stat-val {
  font-size: 15px;
  font-weight: 700;
  color: #e5e7eb;
  margin-top: 2px;
}

.text-accent { color: #9fbee0; }

/* ── JPESA withdrawal ledger ─────────────────────────────────────────────── */
.withdrawal-card {
  border-color: rgba(20, 184, 166, 0.22);
}

.withdrawal-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 14px;
}

.withdrawal-form {
  display: grid;
  grid-template-columns: minmax(140px, 0.8fr) minmax(140px, 0.8fr) minmax(180px, 1fr) auto;
  gap: 10px;
  align-items: end;
}

.withdrawal-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.withdrawal-field span {
  color: #6b7280;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 1px;
  text-transform: uppercase;
}

.withdrawal-field input {
  width: 100%;
  height: 38px;
  background: #0f1623;
  border: 1px solid #253050;
  border-radius: 6px;
  color: #e5e7eb;
  font-size: 13px;
  outline: none;
  padding: 0 10px;
}

.withdrawal-field input:focus {
  border-color: rgba(20, 184, 166, 0.58);
}

.withdrawal-submit,
.withdrawal-secondary {
  height: 38px;
  border-radius: 6px;
  font-size: 11px;
  font-weight: 800;
  cursor: pointer;
  white-space: nowrap;
}

.withdrawal-submit {
  background: rgba(20, 184, 166, 0.18);
  border: 1px solid rgba(20, 184, 166, 0.36);
  color: #2dd4bf;
  padding: 0 14px;
}

.withdrawal-secondary {
  background: rgba(143, 179, 217, 0.12);
  border: 1px solid rgba(143, 179, 217, 0.32);
  color: #8fb3d9;
  padding: 0 12px;
}

.withdrawal-submit:hover,
.withdrawal-secondary:hover {
  filter: brightness(1.12);
}

.withdrawal-submit:disabled,
.withdrawal-secondary:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.withdrawal-error {
  color: #ef4444;
  font-size: 11px;
  margin: 10px 0 0;
}

.withdrawal-list {
  border-top: 1px solid #1a2540;
  margin-top: 14px;
  padding-top: 8px;
}

.withdrawal-row {
  display: grid;
  grid-template-columns: 90px 1fr 120px;
  gap: 10px;
  align-items: center;
  min-height: 30px;
  color: #9ca3af;
  font-size: 12px;
}

.withdrawal-date {
  color: #6b7280;
  white-space: nowrap;
}

.withdrawal-ref {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.withdrawal-amount {
  color: #2dd4bf;
  font-weight: 800;
  text-align: right;
}

/* ── Data Table ──────────────────────────────────────────────────────────── */
.table-wrap {
  overflow-x: auto;
  margin-top: 12px;
}

.data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
}

.data-table th {
  text-align: left;
  padding: 8px 10px;
  font-size: 9px;
  font-weight: 700;
  color: #4b5563;
  letter-spacing: 1px;
  text-transform: uppercase;
  border-bottom: 1px solid #1a2540;
  white-space: nowrap;
}

.data-table td {
  padding: 10px 10px;
  border-bottom: 1px solid #111827;
  color: #9ca3af;
  vertical-align: middle;
}

.data-table tr:hover td {
  background: #0f1623;
}

.td-muted   { color: #374151; font-size: 11px; }
.td-date    { color: #6b7280; white-space: nowrap; }
.td-method  { font-weight: 600; color: #3b82f6; }
.td-amount  { font-weight: 700; color: #e5e7eb; text-align: right; }
.td-commission { font-weight: 800; color: #8fb3d9; text-align: right; }
.td-action  { text-align: right; white-space: nowrap; }
.td-empty   { text-align: center; color: #374151; padding: 24px; font-size: 12px; }

.ledger-note {
  margin: 14px 0 0;
  padding-top: 12px;
  border-top: 1px solid #1a2540;
  color: #6b7280;
  font-size: 11px;
  line-height: 1.5;
}

code {
  background: #1a2540;
  color: #8fb3d9;
  padding: 1px 6px;
  border-radius: 4px;
  font-size: 11px;
}

.plan-chip {
  background: #1a2540;
  color: #9ca3af;
  font-size: 10px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 4px;
}

/* ── Status Badges ───────────────────────────────────────────────────────── */
.status-badge {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.5px;
  padding: 3px 8px;
  border-radius: 4px;
  text-transform: uppercase;
}

.st-done { background: rgba(16,185,129,0.12); color: #10b981; border: 1px solid rgba(16,185,129,0.2); }
.st-proc { background: rgba(59,130,246,0.12);  color: #3b82f6; border: 1px solid rgba(59,130,246,0.2); }
.st-pend { background: rgba(143,179,217,.12); color: #9fbee0; border: 1px solid rgba(143,179,217,.2); }
.st-fail { background: rgba(239,68,68,0.12);   color: #ef4444; border: 1px solid rgba(239,68,68,0.2); }
.st-none { background: rgba(107,114,128,0.12); color: #6b7280; border: 1px solid rgba(107,114,128,0.2); }

.commission-error {
  max-width: 230px;
  margin: 6px 0 0;
  color: #ef4444;
  font-size: 10px;
  line-height: 1.35;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.retry-commission-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  min-width: 72px;
  height: 28px;
  padding: 0 9px;
  border: 1px solid rgba(143,179,217,.32);
  border-radius: 6px;
  background: rgba(143,179,217,.12);
  color: #8fb3d9;
  font-size: 11px;
  font-weight: 800;
  cursor: pointer;
}

.retry-commission-btn svg {
  width: 13px;
  height: 13px;
  flex: 0 0 auto;
}

.retry-commission-btn:hover {
  background: rgba(143,179,217,.2);
  border-color: rgba(143,179,217,.48);
}

.retry-commission-btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.action-muted {
  color: #374151;
  font-size: 12px;
}

/* ── Support insights ───────────────────────────────────────────────────── */
.insights-toolbar {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 16px;
}

.insights-eyebrow {
  margin: 0;
  color: #d1d5db;
  font-size: 13px;
  font-weight: 700;
}

.insights-range {
  margin: 4px 0 0;
  color: #4b5563;
  font-size: 10px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.period-switcher {
  display: inline-flex;
  padding: 3px;
  border: 1px solid #1f2937;
  border-radius: 8px;
  background: #0f1623;
}

.period-btn {
  min-height: 30px;
  padding: 0 11px;
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: #6b7280;
  font: inherit;
  font-size: 10px;
  font-weight: 700;
  cursor: pointer;
}

.period-btn:hover:not(:disabled) { color: #d1d5db; }
.period-btn.active { background: #1a2540; color: #8fb3d9; }
.period-btn:disabled { cursor: wait; opacity: 0.65; }

.insights-state {
  min-height: 260px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  color: #6b7280;
  font-size: 12px;
}

.insights-state--error {
  flex-direction: column;
  color: #f87171;
}

.insights-state--error button {
  border: 1px solid #253050;
  border-radius: 6px;
  background: #1a2540;
  color: #e5e7eb;
  padding: 7px 16px;
  cursor: pointer;
}

.insights-brief {
  display: grid;
  grid-template-columns: 74px minmax(0, 1fr);
  overflow: hidden;
  border: 1px solid rgba(59, 130, 246, 0.28);
  border-radius: 12px;
  background: #111a27;
}

.brief-marker {
  display: flex;
  align-items: center;
  justify-content: center;
  border-right: 1px solid rgba(59, 130, 246, 0.22);
  color: #60a5fa;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.18em;
  writing-mode: vertical-rl;
  transform: rotate(180deg);
}

.brief-copy { padding: 22px 24px; }

.brief-copy h2 {
  max-width: 820px;
  margin: 0;
  color: #f3f4f6;
  font-size: clamp(18px, 2vw, 25px);
  line-height: 1.2;
}

.brief-copy > p {
  margin: 9px 0 0;
  color: #6b7280;
  font-size: 12px;
}

.brief-highlights {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 16px;
  margin-top: 12px;
}

.brief-highlights span {
  position: relative;
  padding-left: 12px;
  color: #9ca3af;
  font-size: 11px;
}

.brief-highlights span::before {
  content: '';
  position: absolute;
  top: 5px;
  left: 0;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: #3b82f6;
}

.insights-grid { margin-top: 16px; }
.insights-bar-label { width: 108px; }
.insights-bar-value { width: 30px; }

.sentiment-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  margin-top: 18px;
}

.sentiment-cell {
  display: flex;
  min-height: 74px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  border: 1px solid #1f2937;
  border-radius: 8px;
  background: #0f1623;
}

.sentiment-value { color: #e5e7eb; font-size: 20px; font-weight: 800; }
.sentiment-label { margin-top: 4px; color: #6b7280; font-size: 9px; text-transform: uppercase; }
.sentiment-cell--positive { border-bottom-color: rgba(16, 185, 129, 0.65); }
.sentiment-cell--neutral { border-bottom-color: rgba(107, 114, 128, 0.65); }
.sentiment-cell--frustrated { border-bottom-color: rgba(249, 115, 22, 0.65); }
.sentiment-cell--angry { border-bottom-color: rgba(239, 68, 68, 0.65); }

.negative-meter {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid #1f2937;
  color: #6b7280;
  font-size: 11px;
}

.negative-meter strong { color: #f97316; font-size: 14px; }

.theme-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1px;
  overflow: hidden;
  margin-top: 14px;
  border: 1px solid #1f2937;
  background: #1f2937;
}

.theme-card {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  gap: 12px;
  min-height: 126px;
  padding: 16px;
  background: #0f1623;
}

.theme-rank {
  color: #374151;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 22px;
  font-weight: 800;
}

.theme-main h3 { margin: 0; color: #e5e7eb; font-size: 13px; }
.theme-main > p { margin: 8px 0 12px; color: #6b7280; font-size: 11px; line-height: 1.5; }

.theme-title-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.theme-title-row > span {
  flex-shrink: 0;
  color: #8fb3d9;
  font-size: 9px;
  font-weight: 800;
  text-transform: uppercase;
}

.theme-meta { display: flex; gap: 12px; color: #4b5563; font-size: 9px; text-transform: uppercase; }

.insights-bottom-grid {
  display: grid;
  grid-template-columns: minmax(0, 0.8fr) minmax(0, 1.2fr);
  gap: 16px;
  margin-top: 16px;
}

.feedback-list {
  max-height: 330px;
  overflow-y: auto;
  margin-top: 8px;
  padding-right: 4px;
}

.feedback-item {
  padding: 12px 0;
  border-bottom: 1px solid #1f2937;
}

.feedback-item:last-child { border-bottom: 0; }

.feedback-head { display: flex; align-items: center; gap: 7px; }
.feedback-head time { margin-left: auto; color: #374151; font-size: 9px; }
.feedback-item > p { margin: 8px 0 0; color: #9ca3af; font-size: 11px; line-height: 1.5; }

.feedback-category,
.feedback-sentiment {
  padding: 3px 6px;
  border-radius: 4px;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.feedback-category { background: rgba(59, 130, 246, 0.12); color: #60a5fa; }
.feedback-sentiment { background: rgba(107, 114, 128, 0.12); color: #9ca3af; }
.feedback-sentiment--positive { color: #34d399; }
.feedback-sentiment--frustrated { color: #fb923c; }
.feedback-sentiment--angry { color: #f87171; }

/* ── Gateway control ───────────────────────────────────────────────────── */
.gateway-panel { max-width: 1040px; }
.gateway-callout {
  display: flex;
  justify-content: space-between;
  gap: 24px;
  padding: 26px;
  border: 1px solid #23304a;
  background: #0d1422;
}
.gateway-eyebrow { color: #60a5fa; font-size: 9px; font-weight: 900; letter-spacing: .16em; }
.gateway-callout h2 { margin: 8px 0 7px; color: #f8fafc; font-size: 24px; }
.gateway-callout p { max-width: 680px; margin: 0; color: #7f8ca3; font-size: 12px; line-height: 1.65; }
.gateway-live { align-self: flex-start; display: inline-flex; align-items: center; gap: 7px; color: #34d399; font-size: 10px; font-weight: 800; text-transform: uppercase; }
.gateway-live i { width: 7px; height: 7px; border-radius: 50%; background: currentColor; box-shadow: 0 0 0 5px rgba(52, 211, 153, .08); }
.gateway-live--busy { color: #9fbee0; }
.gateway-error { margin: 14px 0 0; padding: 11px 13px; border: 1px solid rgba(248,113,113,.2); border-radius: 8px; background: rgba(248, 113, 113, .07); color: #fca5a5; font-size: 11px; }
.gateway-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; margin-top: 16px; }
.gateway-card { padding: 22px; border: 1px solid #1f2a3d; background: #0c121e; transition: border-color .2s, background .2s; }
.gateway-card--active { border-color: rgba(52, 211, 153, .48); background: #0c171b; }
.gateway-card-head { display: flex; justify-content: space-between; gap: 16px; align-items: flex-start; }
.gateway-provider-code { color: #4b5870; font-size: 8px; font-weight: 900; letter-spacing: .18em; }
.gateway-card h3 { margin: 5px 0 0; color: #f8fafc; font-size: 20px; }
.gateway-active-pill, .gateway-ready-pill { padding: 5px 7px; border: 1px solid; font-size: 8px; font-weight: 900; letter-spacing: .08em; }
.gateway-active-pill, .gateway-ready-pill.is-ready { border-color: rgba(52, 211, 153, .35); color: #34d399; }
.gateway-ready-pill.is-missing { border-color: rgba(248, 113, 113, .35); color: #f87171; }
.gateway-status-copy { min-height: 34px; margin: 18px 0; color: #7f8ca3; font-size: 11px; line-height: 1.5; }
.gateway-capabilities { display: flex; gap: 8px; flex-wrap: wrap; }
.gateway-capabilities span { padding: 5px 8px; background: #111b2b; color: #8ea0bb; font-size: 9px; }
.gateway-missing { display: flex; gap: 5px; flex-wrap: wrap; margin-top: 12px; }
.gateway-missing span { color: #fca5a5; font-family: monospace; font-size: 9px; }
.gateway-actions { display: flex; gap: 8px; margin-top: 24px; }
.gateway-actions button { flex: 1; padding: 10px 12px; border: 1px solid #2a3850; background: transparent; color: #b5c1d2; font-size: 10px; font-weight: 800; cursor: pointer; }
.gateway-actions button:disabled { opacity: .42; cursor: not-allowed; }
.gateway-actions .gateway-switch-btn { border-color: #3b82f6; background: #2563eb; color: white; }
.gateway-audit { display: flex; align-items: center; gap: 8px; margin-top: 14px; color: #59677d; font-size: 10px; }
.gateway-audit strong { color: #9aa8bb; }

/* ── Responsive ──────────────────────────────────────────────────────────── */
@media (max-width: 1100px) {
  .kpi-grid       { grid-template-columns: repeat(2, 1fr); }
  .two-col-grid   { grid-template-columns: 1fr; }
  .chart-row      { grid-template-columns: 1fr; }
  .theme-grid     { grid-template-columns: 1fr; }
  .insights-bottom-grid { grid-template-columns: 1fr; }
  .withdrawal-form { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .withdrawal-submit { width: 100%; }
  .gateway-grid { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  .dev-dash       { display: block; min-height: 100dvh; overflow-x: hidden; }
  .d-sidebar {
    display: flex;
    z-index: 1001;
    width: min(86vw, 300px);
    height: 100dvh;
    transform: translateX(-105%);
    transition: transform 0.24s ease;
    box-shadow: 24px 0 70px rgba(0,0,0,0.55);
  }
  .d-sidebar.is-mobile-open { transform: translateX(0); }
  .d-mobile-backdrop {
    display: block;
    position: fixed;
    inset: 0;
    z-index: 1000;
    width: 100%;
    height: 100%;
    border: 0;
    background: rgba(3,7,18,0.72);
    backdrop-filter: blur(3px);
  }
  .d-mobile-toggle {
    display: inline-flex;
    width: 42px;
    height: 42px;
    flex: 0 0 42px;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 5px;
    border: 1px solid rgba(143,179,217,.34);
    border-radius: 8px;
    background: rgba(143,179,217,.1);
  }
  .d-mobile-toggle span { width: 18px; height: 2px; border-radius: 2px; background: #8fb3d9; }
  .d-mobile-close {
    display: block;
    position: relative;
    width: 36px;
    height: 36px;
    margin-left: auto;
    flex: 0 0 36px;
    border: 1px solid #253050;
    border-radius: 7px;
    background: #111b2b;
  }
  .d-mobile-close span { position: absolute; top: 16px; left: 9px; width: 16px; height: 2px; background: #9aa8bb; }
  .d-mobile-close span:first-child { transform: rotate(45deg); }
  .d-mobile-close span:last-child { transform: rotate(-45deg); }
  .d-main         { margin-left: 0; }
  .kpi-grid       { grid-template-columns: 1fr 1fr; }
  .d-body         { padding: 16px; }
  .d-header       { padding: 14px 16px; align-items: center; }
  .insights-toolbar { align-items: stretch; flex-direction: column; }
  .period-switcher { align-self: flex-start; }
  .insights-brief { grid-template-columns: 44px minmax(0, 1fr); }
  .sentiment-grid { grid-template-columns: repeat(2, 1fr); }
  .withdrawal-head { flex-direction: column; }
  .withdrawal-form { grid-template-columns: 1fr; }
  .withdrawal-row  { grid-template-columns: 78px 1fr 104px; }
  .gateway-callout { flex-direction: column; }
}

/* ── Executive visual system ───────────────────────────────────────────── */
.dev-dash {
  --d-ink: #0b0f14;
  --d-sidebar: #0e141d;
  --d-panel: #121923;
  --d-elevated: #17212d;
  --d-line: rgba(148, 163, 184, .11);
  --d-accent: #8fb3d9;
  --d-accent-strong: #b7d0e8;
  --d-text: #f2f5f7;
  --d-muted: #8290a3;
  min-height: 100dvh;
  background: var(--d-ink);
  color: var(--d-text);
  font-family: 'Outfit Variable', 'Avenir Next', system-ui, sans-serif;
  font-variant-numeric: tabular-nums;
}
.d-sidebar {
  width: 252px;
  border: 0;
  background: var(--d-sidebar);
  box-shadow: 18px 0 45px rgba(2, 6, 12, .22);
